import React, { useState, useEffect } from "react";
import {
  Container,
  Row,
  Col,
  TabContent,
  TabPane,
  Nav,
  NavItem,
  NavLink,
  Form,
  FormGroup,
  Input,
  Table,
  Button,
} from "reactstrap";
import classnames from "classnames";
import { FaTrashAlt, FaPlusCircle } from "react-icons/fa";
import api from "../../constants/api";

const PurchaseOrderPage = () => {
  const [activeTab, setActiveTab] = useState("1");
  const [supplierData, setSupplierData] = useState({});
  const [tableData, setTableData] = useState([]);
  const [supplierOptions, setSupplierOptions] = useState([]);
  const [rows, setRows] = useState([
    {
      productCode: "",
      productName: "",
      cartonQty: 0,
      looseQty: 0,
      cartonPrice: 0,
      qty: 0,
      price: 0,
      discount: 0,
      totalPrice: 0,
    },
  ]);

  useEffect(() => {
    // Fetch supplier form data
    api.get("/api/supplier-info").then((response) => {
      setSupplierData(response.data);
    });

    // Fetch table data
    api.get("/api/supplier-products").then((response) => {
      setTableData(response.data);
    });

    // Fetch supplier options for dropdown
    api.get("/api/supplier-options").then((response) => {
      setSupplierOptions(response.data);
    });
  }, []);

  const toggleTab = (tab) => {
    if (activeTab !== tab) {
      setActiveTab(tab);
    }
  };

  const handleRowChange = (index, field, value) => {
    const updatedRows = [...rows];
    updatedRows[index][field] = value;

    if (["cartonQty", "cartonPrice", "looseQty", "discount"].includes(field)) {
      const cartonTotal = updatedRows[index].cartonQty * updatedRows[index].cartonPrice;
      const looseTotal = updatedRows[index].looseQty * (updatedRows[index].cartonPrice / 12);
      const grossTotal = cartonTotal + looseTotal;
      const finalTotal = grossTotal - updatedRows[index].discount;

      updatedRows[index].qty = updatedRows[index].cartonQty + updatedRows[index].looseQty;
      updatedRows[index].totalPrice = parseFloat(finalTotal.toFixed(2));
    }

    setRows(updatedRows);
  };

  const addRow = (index) => {
    const newRow = {
      productCode: "",
      productName: "",
      cartonQty: 0,
      looseQty: 0,
      cartonPrice: 0,
      qty: 0,
      price: 0,
      discount: 0,
      totalPrice: 0,
    };
    const updatedRows = [...rows];
    updatedRows.splice(index + 1, 0, newRow);
    setRows(updatedRows);
  };

  const deleteRow = (index) => {
    if (rows.length > 1) {
      setRows(rows.filter((_, i) => i !== index));
    }
  };

  return (
    <Container className="mt-4">
      <h2>Add/Edit Purchase Order</h2>
      <Nav tabs>
        <NavItem>
          <NavLink
            className={classnames({ active: activeTab === "1" })}
            onClick={() => toggleTab("1")}
          >
            Supplier
          </NavLink>
        </NavItem>
        <NavItem>
          <NavLink
            className={classnames({ active: activeTab === "2" })}
            onClick={() => toggleTab("2")}
          >
            Currency
          </NavLink>
        </NavItem>
      </Nav>

      <TabContent activeTab={activeTab}>
        <TabPane tabId="1">
          <Form className="mt-3">
            <Row>
              <Col md="6">
                <FormGroup>
                  <label>Supplier Code</label>
                  <Input type="text" placeholder="Enter supplier code" value={supplierData.supplierCode || ""} readOnly />
                </FormGroup>
              </Col>
              <Col md="6">
                <FormGroup>
                  <label>Supplier Name</label>
                  <Input type="select">
                    <option value="">Select Supplier</option>
                    {supplierOptions.map((supplier, index) => (
                      <option key={index} value={supplier.id}>
                        {supplier.name}
                      </option>
                    ))}
                  </Input>
                </FormGroup>
              </Col>
              <Col md="6">
                <FormGroup>
                  <label>Contact Person</label>
                  <Input type="text" placeholder="Enter contact person" value={supplierData.contactPerson || ""} readOnly />
                </FormGroup>
              </Col>
              <Col md="6">
                <FormGroup>
                  <label>Contact Address1</label>
                  <Input type="text" placeholder="Enter contact address" value={supplierData.address1 || ""} readOnly />
                </FormGroup>
              </Col>
              <Col md="6">
                <FormGroup>
                  <label>Contact Address2</label>
                  <Input type="text" placeholder="Enter contact address" value={supplierData.address2 || ""} readOnly />
                </FormGroup>
              </Col>
              <Col md="6">
                <FormGroup>
                  <label>Contact Address3</label>
                  <Input type="text" placeholder="Enter contact address" value={supplierData.address3 || ""} readOnly />
                </FormGroup>
              </Col>
              <Col md="6">
                <FormGroup>
                  <label>Country/Postal Code</label>
                  <Input type="text" placeholder="Country / Postal code" value={supplierData.countryPostal || ""} readOnly />
                </FormGroup>
              </Col>
              <Col md="6">
                <FormGroup>
                  <label>Remarks</label>
                  <Input type="textarea" placeholder="Remarks" />
                </FormGroup>
              </Col>
              <Col md="6">
                <FormGroup>
                  <label>Request Delivery Date</label>
                  <Input type="date" />
                </FormGroup>
              </Col>
            </Row>
          </Form>
        </TabPane>

        <TabPane tabId="2">
      
          <Form className="mt-3">
            <Row>
              <Col md="6">
                <FormGroup>
                  <label>Currency Code</label>
                  <Input type="text" placeholder="Enter supplier code" value={supplierData.currencyCode || ""} readOnly />
                </FormGroup>
              </Col>
              <Col md="6">
                <FormGroup>
                  <label>Currency Name</label>
                  <Input type="select">
                    <option value="">Select Supplier</option>
                    {supplierOptions.map((supplier, index) => (
                      <option key={index} value={supplier.id}>
                        {supplier.name}
                      </option>
                    ))}
                  </Input>
                </FormGroup>
              </Col>
              <Col md="6">
                <FormGroup>
                  <label>Contact Rate</label>
                  <Input type="text" placeholder="Enter contact person" value={supplierData.currency_rate || ""} readOnly />
                </FormGroup>
              </Col>
             
            </Row>
          </Form>
        
        </TabPane>
      </TabContent>

      <h4 className="mt-4">Products</h4>
      <Table bordered>
        <thead>
          <tr>
            <th>S No</th>
            <th>Product Code</th>
            <th>Product Name</th>
            <th>Carton Qty</th>
            <th>Loose Qty</th>
            <th>Qty</th>
            <th>Carton Price</th>
            <th>Price</th>
            <th>Discount</th>
            <th>Total Price</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody>
          {rows.map((row, index) => (
            <tr key={index}>
              <td>{index + 1}</td>
              <td>
                <Input
                  type="text"
                  value={row.productCode}
                  onChange={(e) => handleRowChange(index, "productCode", e.target.value)}
                />
              </td>
              <td>
                <Input
                  type="text"
                  value={row.productName}
                  onChange={(e) => handleRowChange(index, "productName", e.target.value)}
                />
              </td>
              <td>
                <Input
                  type="number"
                  value={row.cartonQty}
                  onChange={(e) => handleRowChange(index, "cartonQty", parseInt(e.target.value) || 0)}
                />
              </td>
              <td>
                <Input
                  type="number"
                  value={row.looseQty}
                  onChange={(e) => handleRowChange(index, "looseQty", parseInt(e.target.value) || 0)}
                />
              </td>
              <td>{row.qty}</td>
              <td>
                <Input
                  type="number"
                  value={row.cartonPrice}
                  onChange={(e) => handleRowChange(index, "cartonPrice", parseFloat(e.target.value) || 0)}
                />
              </td>
              <td>{row.price}</td>
              <td>
                <Input
                  type="number"
                  value={row.discount}
                  onChange={(e) => handleRowChange(index, "discount", parseFloat(e.target.value) || 0)}
                />
              </td>
              <td>{row.totalPrice.toFixed(2)}</td>
              <td>
                <FaTrashAlt
                  style={{ color: "red", cursor: "pointer", marginRight: "10px" }}
                  onClick={() => deleteRow(index)}
                />
                <FaPlusCircle
                  style={{ color: "green", cursor: "pointer" }}
                  onClick={() => addRow(index)}
                />
              </td>
            </tr>
          ))}
        </tbody>
      </Table>

      <div className="mt-4">
        <h5>Summary:</h5>
        <p>Total Products: {rows.length}</p>
        <p>Total Amount: ${rows.reduce((sum, row) => sum + row.totalPrice, 0).toFixed(2)}</p>
        <Button color="success">Save</Button>
        <Button color="secondary" className="ms-2">
          Print
        </Button>
        <Button color="danger" className="ms-2">
          Cancel
        </Button>
      </div>
    </Container>
  );
};

export default PurchaseOrderPage;